window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-64cf47801a43feb5"]={"versions": [{"id": "FIG-64cf47801a43feb5", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architekturschaubild, bestehend aus einem funktionalen Dekompositions-/Datenflussdiagramm (Schichtenarchitektur) und einer tabellarischen Schnittstellenspezifikation (Data Dictionary / Port-Interface-Katalog).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Entstammt dem informativen AUTOSAR-Konzeptdokument <code>AUTOSAR_CP_EXP_AIADASAndVMC</code>. Es spezifiziert die Erfassung, Aggregation und Bereitstellung des Insassenzustands (<code>Occupants State</code>) über Schichtgrenzen hinweg. Der Zweck ist die Bereitstellung einer verlässlichen Zustandsbasis für das Degradations- und Ausfallmanagement (<code>App function outage judgment</code>) zur Freigabe oder Abschaltung automatisierter Fahr- und Assistenzfunktionen (ACC, AEB, LKA).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schichten & Funktionsblöcke:</strong></li>\n<li><code>ADAS-MGR Layer</code> (ADAS Manager / AMG): Untere Aggregationsebene. Konsolidiert Rohsensordaten in zwei primäre Zustandsdomänen:</li>\n<li><code>Occupants seating posture</code>: Erfasst Sitzposition und Gurtsicherung (Sitzbelegungssensoren, Gurtschlosssensoren, Interior-Radar/UWB).</li>\n<li><code>Driver driving consciousness</code>: Erfasst Fahreraufmerksamkeit und Vigilanz (Driver Monitoring Camera / DMS, kapazitive Hands-On-Detection am Lenkrad).</li>\n<li><code>Occupants State</code>: Aggregierender Funktionsbaustein innerhalb des AMG.</li>\n<li><code>ADAS App Layer</code>: Beherbergt funktionale Konsumenten und die Überwachungsinstanz <code>App function outage judgment</code>.</li>\n<li>Zielapplikationen (<code>Output destination</code>): ACC (Adaptive Cruise Control), AEB (Autonomous Emergency Braking), LKA (Lane Keeping Assist).</li>\n<li><strong>Schnittstellendefinition (Port-Interface / Signal <code>PLN2</code>):</strong></li>\n<li><strong>Kategorie:</strong> <code>PLN2</code></li>\n<li><strong>Datenelement:</strong> <code>Occupants State</code></li>\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver (1:n, Sender: <code>AMG</code>, Empfänger: <code>App function outage judgment</code> / Applikationen).</li>\n<li><strong>Typdefinition & Wertebereiche (Variantenvergleich):</strong></li>\n<li><strong>Variante <code>ex.1</code> (Orthogonale Vollmatrix / Diskrete Zustandskombination):</strong></li>\n<li><code>0</code>: <em>Indefinite</em> (Initialwert / ungültig)</li>\n<li><code>1</code>: <code>[Occupants seated - OK] &amp;&amp; [Driver driving consciousness - OK]</code></li>\n<li><code>2</code>: <code>[Occupants seated - OK] &amp;&amp; [Driver driving consciousness - Warning]</code></li>\n<li><code>3</code>: <code>[Occupants seated - OK] &amp;&amp; [Driver driving consciousness - NG]</code></li>\n<li><code>4</code>: <code>[Occupants seated - NG] &amp;&amp; [Driver driving consciousness - OK]</code></li>\n<li><code>5</code>: <code>[Occupants seated - NG] &amp;&amp; [Driver driving consciousness - Warning]</code></li>\n<li><code>6</code>: <code>[Occupants seated - NG] &amp;&amp; [Driver driving consciousness - NG]</code></li>\n<li><strong>Variante <code>ex.2</code> (Abstrahierte Klassifikation / Verdichteter Status):</strong></li>\n<li><code>0</code>: <em>Indefinite</em> (Initialwert)</li>\n<li><code>1</code>: <code>Occupants state - OK</code></li>\n<li><code>2</code>: <code>Occupants state - Need a warning</code></li>\n<li><code>3</code>: <code>Occupants state - NG</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sensordatenerfassung (Zyklisch / Asynchron):</strong> Rohwert-Sampling über Peripherietreiber (DMS, Lenkradsensorik, Sitzbelegungs-ECU) in den ADAS-Manager.</li>\n<li><strong>Vorverarbeitung & Validierung:</strong> Bewertung der Einzelpfade <code>Occupants seating posture</code> und <code>Driver driving consciousness</code> im AMG.</li>\n<li><strong>Zustandsaggregation & RTE-Distribution:</strong> Der AMG aggregiert die Subzustände deterministisch gemäß Abbildungslogik (<code>ex.1</code> oder <code>ex.2</code>) und serialisiert das Signal <code>PLN2</code> an den VFB / die RTE.</li>\n<li><strong>Applikationsbewertung (<code>Outage Judgment</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wert <code>0</code> (<code>Indefinite</code>, z. B. während der Sensorinitialisierung oder bei Systemfehlern): Funktionen verbleiben im gesperrten/nicht-verfügbaren Zustand.</li>\n<li>Wert <code>1</code> (<code>OK</code>): Vollständige Funktionsfreigabe für ACC, AEB und LKA.</li>\n<li>Wert <code>2</code> / <code>Warning</code>: Auslösen optischer/haptischer Take-Over-Requests (TOR) oder Übergang in vorbereitende Warnstufen; Degradations-Timer startet.</li>\n<li>Wert <code>3</code> ff. / <code>NG</code>: Unverzüglicher Funktionsentzug, Übergang in den sicheren Zustand (Safe State / Minimum Risk Maneuver) oder Unterdrückung der Funktionsaktivierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Datentyp-Modellierung:</strong> In AUTOSAR CP als Sender-Receiver-Interface (<code>VariableDataPrototype</code>) mit einem <code>ImplementationDataType</code> basierend auf <code>uint8</code> als Enumeration zu implementieren.</li>\n<li><strong>Architekturentscheidung <code>ex.1</code> vs. <code>ex.2</code>:</strong></li>\n<li><code>ex.1</code> entkoppelt die Sensorschicht weniger stark, ermöglicht aber funktionsspezifische Reaktionen in der Applikation (z. B. AEB bleibt bei unaufmerksamem Fahrer aktiv, LKA/ACC schalten ab).</li>\n<li><code>ex.2</code> verlagert die gesamte Entscheidungslogik in den ADAS-Manager, wodurch Applikationen schlank und austauschbar bleiben.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262):</strong></li>\n<li>Einstufung typischerweise bis ASIL B/D (abhängig vom Hazard-Potential einer fehlerhaften Deaktivierung oder unzulässigen Freigabe automatisierter Längs-/Querführung).</li>\n<li>Der Initialwert <code>0</code> (<code>Indefinite</code>) verhindert Race Conditions beim Boot-Vorgang; Funktionsaufrufe müssen defensiv gegen Nicht-Initialisierung abgesichert sein.</li>\n<li>Bei ECU-übergreifender Verteilung (z. B. AMG auf zentralem ADAS-Domain-Controller, Applikationen auf Zonenrechnern) ist eine E2E-Absicherung (CRC, Alive-Counter via E2E-Profile) des Signals <code>PLN2</code> zwingend erforderlich.</li>\n</ul>"}, {"id": "FIG-978287ea0fe25218", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Hybrides Architekturschaubild, bestehend aus einem funktionalen Dekompositions-/Datenflussdiagramm (Schichtenarchitektur) und einer tabellarischen Schnittstellenspezifikation (Data Dictionary / Port-Interface-Katalog).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Entstammt dem informativen AUTOSAR-Konzeptdokument <code>AUTOSAR_CP_EXP_AIADASAndVMC</code>. Es spezifiziert die Erfassung, Aggregation und Bereitstellung des Insassenzustands (<code>Occupants State</code>) über Schichtgrenzen hinweg. Der Zweck ist die Bereitstellung einer verlässlichen Zustandsbasis für das Degradations- und Ausfallmanagement (<code>App function outage judgment</code>) zur Freigabe oder Abschaltung automatisierter Fahr- und Assistenzfunktionen (ACC, AEB, LKA).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schichten & Funktionsblöcke:</strong></li>\n<li><code>ADAS-MGR Layer</code> (ADAS Manager / AMG): Untere Aggregationsebene. Konsolidiert Rohsensordaten in zwei primäre Zustandsdomänen:</li>\n<li><code>Occupants seating posture</code>: Erfasst Sitzposition und Gurtsicherung (Sitzbelegungssensoren, Gurtschlosssensoren, Interior-Radar/UWB).</li>\n<li><code>Driver driving consciousness</code>: Erfasst Fahreraufmerksamkeit und Vigilanz (Driver Monitoring Camera / DMS, kapazitive Hands-On-Detection am Lenkrad).</li>\n<li><code>Occupants State</code>: Aggregierender Funktionsbaustein innerhalb des AMG.</li>\n<li><code>ADAS App Layer</code>: Beherbergt funktionale Konsumenten und die Überwachungsinstanz <code>App function outage judgment</code>.</li>\n<li>Zielapplikationen (<code>Output destination</code>): ACC (Adaptive Cruise Control), AEB (Autonomous Emergency Braking), LKA (Lane Keeping Assist).</li>\n<li><strong>Schnittstellendefinition (Port-Interface / Signal <code>PLN2</code>):</strong></li>\n<li><strong>Kategorie:</strong> <code>PLN2</code></li>\n<li><strong>Datenelement:</strong> <code>Occupants State</code></li>\n<li><strong>Kommunikationsmuster:</strong> Sender-Receiver (1:n, Sender: <code>AMG</code>, Empfänger: <code>App function outage judgment</code> / Applikationen).</li>\n<li><strong>Typdefinition & Wertebereiche (Variantenvergleich):</strong></li>\n<li><strong>Variante <code>ex.1</code> (Orthogonale Vollmatrix / Diskrete Zustandskombination):</strong></li>\n<li><code>0</code>: <em>Indefinite</em> (Initialwert / ungültig)</li>\n<li><code>1</code>: <code>[Occupants seated - OK] &amp;&amp; [Driver driving consciousness - OK]</code></li>\n<li><code>2</code>: <code>[Occupants seated - OK] &amp;&amp; [Driver driving consciousness - Warning]</code></li>\n<li><code>3</code>: <code>[Occupants seated - OK] &amp;&amp; [Driver driving consciousness - NG]</code></li>\n<li><code>4</code>: <code>[Occupants seated - NG] &amp;&amp; [Driver driving consciousness - OK]</code></li>\n<li><code>5</code>: <code>[Occupants seated - NG] &amp;&amp; [Driver driving consciousness - Warning]</code></li>\n<li><code>6</code>: <code>[Occupants seated - NG] &amp;&amp; [Driver driving consciousness - NG]</code></li>\n<li><strong>Variante <code>ex.2</code> (Abstrahierte Klassifikation / Verdichteter Status):</strong></li>\n<li><code>0</code>: <em>Indefinite</em> (Initialwert)</li>\n<li><code>1</code>: <code>Occupants state - OK</code></li>\n<li><code>2</code>: <code>Occupants state - Need a warning</code></li>\n<li><code>3</code>: <code>Occupants state - NG</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Sensordatenerfassung (Zyklisch / Asynchron):</strong> Rohwert-Sampling über Peripherietreiber (DMS, Lenkradsensorik, Sitzbelegungs-ECU) in den ADAS-Manager.</li>\n<li><strong>Vorverarbeitung & Validierung:</strong> Bewertung der Einzelpfade <code>Occupants seating posture</code> und <code>Driver driving consciousness</code> im AMG.</li>\n<li><strong>Zustandsaggregation & RTE-Distribution:</strong> Der AMG aggregiert die Subzustände deterministisch gemäß Abbildungslogik (<code>ex.1</code> oder <code>ex.2</code>) und serialisiert das Signal <code>PLN2</code> an den VFB / die RTE.</li>\n<li><strong>Applikationsbewertung (<code>Outage Judgment</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wert <code>0</code> (<code>Indefinite</code>, z. B. während der Sensorinitialisierung oder bei Systemfehlern): Funktionen verbleiben im gesperrten/nicht-verfügbaren Zustand.</li>\n<li>Wert <code>1</code> (<code>OK</code>): Vollständige Funktionsfreigabe für ACC, AEB und LKA.</li>\n<li>Wert <code>2</code> / <code>Warning</code>: Auslösen optischer/haptischer Take-Over-Requests (TOR) oder Übergang in vorbereitende Warnstufen; Degradations-Timer startet.</li>\n<li>Wert <code>3</code> ff. / <code>NG</code>: Unverzüglicher Funktionsentzug, Übergang in den sicheren Zustand (Safe State / Minimum Risk Maneuver) oder Unterdrückung der Funktionsaktivierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & Datentyp-Modellierung:</strong> In AUTOSAR CP als Sender-Receiver-Interface (<code>VariableDataPrototype</code>) mit einem <code>ImplementationDataType</code> basierend auf <code>uint8</code> als Enumeration zu implementieren.</li>\n<li><strong>Architekturentscheidung <code>ex.1</code> vs. <code>ex.2</code>:</strong></li>\n<li><code>ex.1</code> entkoppelt die Sensorschicht weniger stark, ermöglicht aber funktionsspezifische Reaktionen in der Applikation (z. B. AEB bleibt bei unaufmerksamem Fahrer aktiv, LKA/ACC schalten ab).</li>\n<li><code>ex.2</code> verlagert die gesamte Entscheidungslogik in den ADAS-Manager, wodurch Applikationen schlank und austauschbar bleiben.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262):</strong></li>\n<li>Einstufung typischerweise bis ASIL B/D (abhängig vom Hazard-Potential einer fehlerhaften Deaktivierung oder unzulässigen Freigabe automatisierter Längs-/Querführung).</li>\n<li>Der Initialwert <code>0</code> (<code>Indefinite</code>) verhindert Race Conditions beim Boot-Vorgang; Funktionsaufrufe müssen defensiv gegen Nicht-Initialisierung abgesichert sein.</li>\n<li>Bei ECU-übergreifender Verteilung (z. B. AMG auf zentralem ADAS-Domain-Controller, Applikationen auf Zonenrechnern) ist eine E2E-Absicherung (CRC, Alive-Counter via E2E-Profile) des Signals <code>PLN2</code> zwingend erforderlich.</li>\n</ul>"}], "trans": [{"from": "FIG-64cf47801a43feb5", "to": "FIG-978287ea0fe25218", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
